}

{
  "high_level_description": "A retro silkscreen-style film festival poster for a fictional event called MIDNIGHT FRAMES, featuring dramatic silhouettes, limited colors, halftone texture, and layered typography.",
  "style_description": {
    "aesthetics": "retro, cinematic, bold, moody, collectible poster art",
    "lighting": "graphic high-contrast lighting with dramatic shadow shapes",
    "medium": "graphic_design",
    "art_style": "vintage silkscreen poster, halftone texture, limited color print, bold editorial typography",
    "color_palette": ["#0E0E10", "#F2E8CF", "#C1121F", "#003049", "#F77F00"]
  },
  "compositional_deconstruction": {
    "background": "A textured paper poster surface with halftone grain, subtle misregistration, and abstract cinematic light beams.",
    "elements": [
      {
        "type": "text",
        "bbox": [45, 110, 150, 890],
        "text": "MIDNIGHT FRAMES",
        "desc": "Large title at the top with bold retro typography and slight print texture.",
        "color_palette": ["#F2E8CF", "#0E0E10", "#C1121F"]
      },
      {
        "type": "text",
        "bbox": [165, 200, 220, 800],
        "text": "INDEPENDENT FILM FESTIVAL",
        "desc": "Subtitle centered under the main title, compact and legible.",
        "color_palette": ["#F2E8CF", "#0E0E10"]
      },
      {
        "type": "obj",
        "bbox": [250, 120, 760, 880],
        "desc": "A dramatic noir-style silhouette of a person standing in front of a large circular moon-like spotlight, with film-strip shapes crossing the composition.",
        "color_palette": ["#0E0E10", "#F2E8CF", "#003049", "#C1121F"]
      },
      {
        "type": "obj",
        "bbox": [370, 90, 820, 910],
        "desc": "Diagonal strips of abstract film frames and rectangular red-orange graphic blocks layered behind and around the central silhouette.",
        "color_palette": ["#C1121F", "#F77F00", "#003049", "#0E0E10"]
      },
      {
        "type": "text",
        "bbox": [805, 180, 865, 820],
        "text": "OCT 17-20  /  CINEMA HALL 7",
        "desc": "Event date and venue near the lower portion of the poster.",
        "color_palette": ["#F2E8CF", "#0E0E10"]
